<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;

/**
 * `transfer_charges` table of the MyAT database.
 * Generated by `php artisan app:generate-models`; add relationships below.
 *
 * @property int|null $ID
 * @property int|null $TransferID
 * @property string|null $TransferCharge
 * @property Carbon|null $ChargeDate
 * @property float|null $ChargeValue
 * @property float|null $Expense
 * @property string|null $ExpenseReason
 * @property string|null $ExpenseReceived
 * @property string|null $ExpensePaid
 * @property string|null $PaymentVia
 * @property int|null $TobeInvoiced
 * @property int|null $Invoiced
 * @property string|null $ElorusID
 * @property string|null $InvoiceNum
 * @property string|null $PaymentStatus
 * @property Carbon|null $ReceiptDate
 * @property string|null $CreatedBy
 * @property Carbon|null $CreatedDate
 * @property string|null $ModifiedBy
 * @property Carbon|null $ModifiedDate
 * @property string|null $PaymentCode
 * @property int|null $ExpenseChargeCategory
 */
class TransferCharge extends Model
{
    protected $table = 'transfer_charges';

    protected $primaryKey = 'ID';

    public $incrementing = true;

    protected $keyType = 'int';

    public $timestamps = false;

    protected $guarded = [];

    protected function casts(): array
    {
        return [
            'ID' => 'integer',
            'TransferID' => 'integer',
            'ChargeDate' => 'date',
            'ChargeValue' => 'float',
            'Expense' => 'float',
            'TobeInvoiced' => 'integer',
            'Invoiced' => 'integer',
            'ReceiptDate' => 'date',
            'CreatedDate' => 'datetime',
            'ModifiedDate' => 'datetime',
            'ExpenseChargeCategory' => 'integer',
        ];
    }

    public const PAYMENT_VIA = ['Viva' => 'Viva', 'Cash' => 'Cash', 'ERB' => 'ERB'];

    /** PHPRunner JS: Viva and ERB payments are invoiced, cash is not. */
    public static function isInvoicedPayment(?string $paymentVia): bool
    {
        return in_array($paymentVia, ['Viva', 'ERB'], true);
    }

    protected static function booted(): void
    {
        static::creating(function (TransferCharge $charge): void {
            $charge->CreatedDate = now();
            $charge->CreatedBy = auth()->user()?->username;
        });

        static::updating(function (TransferCharge $charge): void {
            $charge->ModifiedDate = now();
            $charge->ModifiedBy = auth()->user()?->username;
        });
    }

    public function transfer(): BelongsTo
    {
        return $this->belongsTo(Transfer::class, 'TransferID', 'TransferID');
    }
}
